def vary_aemakecell(cells):
    results = {}
    for cellName, figs in cells:
        pyScript.aeSelectFigs(figs)
        ok = pyScript.aeMakeCell(cellName=cellName, overwrite=True)
        results[cellName] = ok
    return results

